import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第六十四卦 未济 火水未济 离上坎下","description":"周易 - 第六十四卦 未济 火水未济 离上坎下","frontmatter":{"title":"第六十四卦 未济 火水未济 离上坎下","description":"周易 - 第六十四卦 未济 火水未济 离上坎下"},"headers":[],"relativePath":"zh/classics/zhouyi/065.md","filePath":"zh/classics/zhouyi/065.md"}'),l={name:"zh/classics/zhouyi/065.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="未济" tabindex="-1">未济 <a class="header-anchor" href="#未济" aria-label="Permalink to “未济”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>亨，小狐汔济，濡其尾，无攸利。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>未济，亨；柔得中也。小狐汔济，未出中也。濡其尾，无攸利；不续终也。虽不当位，刚柔应也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>火在水上，未济；君子以慎辨物居方。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>濡其尾，吝。象曰：濡其尾，亦不 知极也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>曳其轮，贞吉。象曰：九二贞吉，中以行正也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>未济，征凶，利涉大川。象曰：未济征凶，位不当也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>贞吉，悔亡，震用伐鬼方，三年有赏于大国。象曰：贞吉悔亡，志行也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>贞吉，无悔，君子之光，有孚，吉。象曰：君子之光，其晖吉也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>有孚于饮酒，无咎，濡其首，有孚失是。象曰：饮酒濡首，亦不知节也</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
